-- Schema for calorie_tracker (Release version)
-- Generated by pg_dump + manual migrations

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;

COMMENT ON EXTENSION pg_trgm IS 'text similarity measurement and index searching based on trigrams';

SET default_tablespace = '';
SET default_table_access_method = heap;

-- ==========================================
-- Таблица users
-- ==========================================
CREATE TABLE public.users (
    id bigint NOT NULL,
    email character varying(255) NOT NULL,
    password_hash character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE public.users OWNER TO postgres;

CREATE SEQUENCE public.users_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER TABLE public.users_id_seq OWNER TO postgres;
ALTER SEQUENCE public.users_id_seq OWNED BY public.users.id;
ALTER TABLE ONLY public.users ALTER COLUMN id SET DEFAULT nextval('public.users_id_seq'::regclass);

-- ==========================================
-- Таблица products
-- ==========================================
CREATE TABLE public.products (
    id bigint NOT NULL,
    name character varying(255) NOT NULL,
    kcal_per_100g numeric(7,2) NOT NULL,
    protein_per_100g numeric(7,2) NOT NULL,
    fat_per_100g numeric(7,2) NOT NULL,
    carbs_per_100g numeric(7,2) NOT NULL,
    barcode character varying(100),
    owner_id bigint,
    product_updated timestamp with time zone  -- 2.5: время последнего обновления из OFF
);

ALTER TABLE public.products OWNER TO postgres;

CREATE SEQUENCE public.products_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER TABLE public.products_id_seq OWNER TO postgres;
ALTER SEQUENCE public.products_id_seq OWNED BY public.products.id;
ALTER TABLE ONLY public.products ALTER COLUMN id SET DEFAULT nextval('public.products_id_seq'::regclass);

-- ==========================================
-- Таблица diary_entries
-- ==========================================
CREATE TABLE public.diary_entries (
    id bigint NOT NULL,
    user_id bigint NOT NULL,
    product_id bigint,
    product_name character varying(255) NOT NULL,
    grams numeric(7,2) NOT NULL,
    kcal numeric(9,2) NOT NULL,
    protein numeric(7,2) NOT NULL,
    fat numeric(7,2) NOT NULL,
    carbs numeric(7,2) NOT NULL,
    logged_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    logged_date date NOT NULL DEFAULT CURRENT_DATE,
    meal_type character varying(20),           -- 2.3: breakfast/lunch/dinner/snack
    eaten_at timestamp with time zone NOT NULL -- 2.4: время фактического приёма пищи
);

ALTER TABLE public.diary_entries OWNER TO postgres;

CREATE SEQUENCE public.diary_entries_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER TABLE public.diary_entries_id_seq OWNER TO postgres;
ALTER SEQUENCE public.diary_entries_id_seq OWNED BY public.diary_entries.id;
ALTER TABLE ONLY public.diary_entries ALTER COLUMN id SET DEFAULT nextval('public.diary_entries_id_seq'::regclass);

-- ==========================================
-- PRIMARY KEY
-- ==========================================
ALTER TABLE ONLY public.users ADD CONSTRAINT users_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.products ADD CONSTRAINT products_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.diary_entries ADD CONSTRAINT diary_entries_pkey PRIMARY KEY (id);

-- ==========================================
-- UNIQUE
-- ==========================================
ALTER TABLE ONLY public.users ADD CONSTRAINT uq_users_email UNIQUE (email);
ALTER TABLE ONLY public.products ADD CONSTRAINT products_barcode_key UNIQUE (barcode);

-- ==========================================
-- CHECK constraints
-- ==========================================
ALTER TABLE ONLY public.diary_entries ADD CONSTRAINT diary_entries_carbs_check CHECK ((carbs >= (0)::numeric));
ALTER TABLE ONLY public.diary_entries ADD CONSTRAINT diary_entries_fat_check CHECK ((fat >= (0)::numeric));
ALTER TABLE ONLY public.diary_entries ADD CONSTRAINT diary_entries_grams_check CHECK ((grams > (0)::numeric));
ALTER TABLE ONLY public.diary_entries ADD CONSTRAINT diary_entries_kcal_check CHECK ((kcal >= (0)::numeric));
ALTER TABLE ONLY public.diary_entries ADD CONSTRAINT diary_entries_protein_check CHECK ((protein >= (0)::numeric));

ALTER TABLE ONLY public.products ADD CONSTRAINT products_carbs_per_100g_check CHECK ((carbs_per_100g >= (0)::numeric));
ALTER TABLE ONLY public.products ADD CONSTRAINT products_fat_per_100g_check CHECK ((fat_per_100g >= (0)::numeric));
ALTER TABLE ONLY public.products ADD CONSTRAINT products_kcal_per_100g_check CHECK ((kcal_per_100g >= (0)::numeric));
ALTER TABLE ONLY public.products ADD CONSTRAINT products_protein_per_100g_check CHECK ((protein_per_100g >= (0)::numeric));

-- 2.3: CHECK для meal_type
ALTER TABLE ONLY public.diary_entries 
ADD CONSTRAINT chk_diary_meal_type 
CHECK (meal_type IS NULL OR meal_type IN ('breakfast', 'lunch', 'dinner', 'snack'));

-- ==========================================
-- FOREIGN KEY
-- ==========================================
ALTER TABLE ONLY public.diary_entries ADD CONSTRAINT diary_entries_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.diary_entries ADD CONSTRAINT diary_entries_product_id_fkey FOREIGN KEY (product_id) REFERENCES public.products(id) ON DELETE SET NULL;
ALTER TABLE ONLY public.products ADD CONSTRAINT products_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES public.users(id) ON DELETE CASCADE;

-- ==========================================
-- INDEXES
-- ==========================================
CREATE INDEX idx_users_email ON public.users USING btree (email);
CREATE INDEX idx_products_owner ON public.products USING btree (owner_id);
CREATE INDEX idx_products_name_trgm ON public.products USING gin (name public.gin_trgm_ops);
CREATE INDEX idx_products_barcode ON public.products USING btree (barcode) WHERE (barcode IS NOT NULL);

-- Индексы для diary_entries
CREATE INDEX idx_diary_user_date ON public.diary_entries USING btree (user_id, logged_date);
CREATE INDEX idx_diary_id_user ON public.diary_entries USING btree (id, user_id);

-- 2.2: Индекс для статистики за период (пользователь + время приёма пищи + тип)
CREATE INDEX idx_diary_stats ON public.diary_entries USING btree (user_id, eaten_at, meal_type);
